SELECT COUNT(*)
FROM TB_REPORT
WHERE reporter_user_id = #{reporterUserId}
AND target_type = 'USER'
AND target_id = #{targetUserId}

SELECT report_id AS reportId, reporter_user_id AS reporterUserId, target_type AS targetType, target_id AS targetId, target_user_id AS targetUserId, target_field AS targetField, reason_id AS reasonId, detail, status, action_type AS actionType, processed_by_user_id AS processedByUserId, processed_at AS processedAt, created_at AS createdAt, updated_at AS updatedAt
FROM tb_report
WHERE report_id = #{value}
